// === Tab: Stripe ===
class Stripe {
	constructor(cx, cy, r, pal, a, da = 0) {
		this.cx = cx;
		this.cy = cy;
		this.r = r;
		this.pal = pal;
		this.a = a;
		this.da = da;
	}

	update(f = 1) {
		this.a += this.da * f;	
	}

	draw() {
		push();
			const x = this.cx;
			const y = this.cy;
			const r = this.r;
			const a = this.a;
			const dx = cos(a) * r;
			const dy = sin(a) * r;
			const d1 = createVector(r, 0).rotate(a);
			const d2 = createVector(0, r/3).rotate(a);

			// gradient line
			const ctx = drawingContext;
			const linGrad = ctx.createLinearGradient(x-d1.x, y-d1.y, x+d1.x, y+d1.y);
			for (let j=0; j<epiColors.palette.length; j++) {
				const clr = EpiColors.getColor(epiColors.palette[j], 128);
				const pos = map(j, 0, epiColors.palette.length-1, 0, 1);
				linGrad.addColorStop(pos, clr);
			}
			ctx.fillStyle = linGrad;
			// line(x-d1.x, y-d1.y, x+d1.x, y+d1.y);rdfg

			beginShape();
			vertex(x+d1.x-d2.x, y+d1.y-d2.y);
			vertex(x+d1.x+d2.x, y+d1.y+d2.y);
			vertex(x-d1.x+d2.x, y-d1.y+d2.y);
			vertex(x-d1.x-d2.x, y-d1.y-d2.y);
			endShape(CLOSE);
		pop();
	}
}

