const DF = 0.9, N = 18, FRMS = 300;
let stripes, startFrame; 

// const { Point, Line, Polygon } = EpiShapeSvg;
const { EpiColors } = EpiColorsPckg;
let epiColors;


function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("rotating gradient rectangles");
	frameRate(30);

	// createCanvas(~~(windowHeight*2/3), windowHeight);
	noFill();
	noStroke();
	rectMode(CENTER);

	epiColors = new EpiColors();
	// epiColors.BG = EpiColors.getAdjustedBrightness(EpiColors.getAdjustedSaturation(epiColors.BG, 2), 0.35);
	epiColors.getRandomPalette(true);
	fill(random(epiColors.palette));
	shuffle(epiColors.palette, true);
	epiColors.palette.splice(0, 1);

	var x = ~~(width/2), y = ~~(height/2);
	var r = ~~(max(width, height) / 2.2);

	// getting stripes
	stripes = [];
	for (let i=0; i<N; i++) {
		const f = i/(N-1);
		var a = f * PI * random(0.9, 1/0.9);
		const da = random(0.0038131, 0.0095712) * Math.sign(i%2-0.5);
		const stripe = new Stripe(x, y, r, epiColors.palette, a, da);
		stripes.push(stripe);
	}
	shuffle(stripes, true);

	// rewind
	for (let i=0; i<FRMS; i++) {
		for (const stripe of stripes) stripe.update(-1); //reverse order
	}

	startFrame = frameCount;

	loop();
}

function draw() {
	blendMode(BLEND);
	background("#ffeeff"); // "#ffeeff"); epiColors.getAverageClr()
	// blendMode(MULTIPLY);

	const canUpdate = frameCount < startFrame + FRMS;

	for (const stripe of stripes) {
		stripe.draw();
		if (canUpdate) stripe.update();
	}

	// shifting thru array every n-th frame
	if (canUpdate && frameCount % 10 === 0) stripes.push(stripes.shift());

	// wait additional frames to initialize again
	if (frameCount > startFrame + FRMS * 1.5) setup();
	// // noLoop() removed for animation
}

function mousePressed() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
